  'te', // తెలుగు
  'zh', // 中文
  'ja', // 日本語
];

/// Name of each language in that language, for the language menu.
const languageNames = <String, String>{
  'id': 'Bahasa Indonesia',
  'de': 'Deutsch',
  'en': 'English',
  'es': 'Español',
  'fr': 'Français',
