  'fixed.joinCrossing': ('tubos conectados no cruzamento', 'pipes connected at the crossing', 'tuberías conectadas en el cruce'),
  'fixed.addSupply': ('fonte de água colocada na ponta livre da linha principal', 'water supply placed at the free end of the mainline', 'fuente de agua colocada en el extremo libre de la línea principal'),
  'fixed.resetSettings': ('parâmetros de projeto restaurados aos valores padrão', 'design parameters restored to the defaults', 'parámetros de diseño restaurados a los valores por defecto'),
